{"version":3,"sources":["../scss/profileData.scss","profileData.css","../scss/_mixins.scss","../scss/_variables.scss"],"names":[],"mappings":"AAGA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;EACA,WAAA;ACFF;ADIE;EERE,uCAAA;EACA,gBFQoC;EEPpC,kBAAA;EACA,YCHW;EDIX,eFK8B;EAC9B,mBAAA;ACEJ;ADCE;EACE,aAAA;EACA,sBAAA;EACA,SAAA;EACA,gBAAA;ACCJ;ADEE;EACE,gBAAA;ACAJ;ADGE;EACE,aAAA;EACA,mBAAA;EACA,eAAA;EACA,SAAA;ACDJ;ADIE;EE/BE,uCAAA;EACA,gBF+BoC;EE9BpC,kBAAA;EACA,YCHW;EDIX,eF4B8B;EAC9B,eAAA;ACEJ;ADCE;EEpCE,uCAAA;EACA,gBFoCoC;EEnCpC,kBAAA;EACA,YCHW;EDIX,eFiC8B;EAC9B,WAAA;EACA,gBAAA;EACA,yBAAA;EACA,aAAA;EACA,kBAAA;ACKJ;ADJI;EE3CA,uCAAA;EACA,gBF2CgC;EE1ChC,kBAAA;EACA,cFyCiB;EExCjB,eFwC0B;ACU9B;ADXI;EE3CA,uCAAA;EACA,gBF2CgC;EE1ChC,kBAAA;EACA,cFyCiB;EExCjB,eFwC0B;ACU9B;;ADLA;EACE,WAAA;EACA,gBAAA;EACA,kBAAA;ACQF;;ADJA;EAEI;IACE,eAAA;ECMJ;EDHE;IACE,eAAA;ECKJ;EDDA;IACE,eAAA;ECGF;AACF","file":"profileData.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n.form__wrapper {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  width: 100%;\n\n  & h3 {\n    @include fonts($defaultColor, 21px, 400);\n    margin-bottom: 10px;\n  }\n\n  & form {\n    display: flex;\n    flex-direction: column;\n    gap: 10px;\n    max-width: 460px;\n  }\n\n  & button {\n    max-width: 150px;\n  }\n\n  & label {\n    display: flex;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 10px;\n  }\n\n  & p {\n    @include fonts($defaultColor, 14px, 400);\n    flex: 0 0 200px;\n  }\n\n  & input {\n    @include fonts($defaultColor, 14px, 400);\n    width: 100%;\n    max-width: 250px;\n    border: 1px solid $gray;\n    padding: 10px;\n    border-radius: 7px;\n    &::placeholder {\n      @include fonts(#545454, 14px, 400);\n    }\n  }\n}\n\n.form__fields {\n  width: 100%;\n  max-width: 250px;\n  position: relative;\n}\n\n\n@media(max-width:992px) {\n  .form__wrapper {\n    & form {\n      max-width: none;\n    }\n  \n    & input {\n      max-width: none;\n    }\n  }\n\n  .form__fields {\n    max-width: none;\n  }\n\n}",".form__wrapper {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  width: 100%;\n}\n.form__wrapper h3 {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 21px;\n  margin-bottom: 10px;\n}\n.form__wrapper form {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  max-width: 460px;\n}\n.form__wrapper button {\n  max-width: 150px;\n}\n.form__wrapper label {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n.form__wrapper p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  flex: 0 0 200px;\n}\n.form__wrapper input {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  width: 100%;\n  max-width: 250px;\n  border: 1px solid #D4D4D4;\n  padding: 10px;\n  border-radius: 7px;\n}\n.form__wrapper input::placeholder {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 14px;\n}\n\n.form__fields {\n  width: 100%;\n  max-width: 250px;\n  position: relative;\n}\n\n@media (max-width: 992px) {\n  .form__wrapper form {\n    max-width: none;\n  }\n  .form__wrapper input {\n    max-width: none;\n  }\n  .form__fields {\n    max-width: none;\n  }\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);"]}2;\n$asideExitColor: rgb(0, 128, 0);"]}